fn poll(n: Int) -> Int uses net {
    if n <= 0 {
        return 0
    }
    check fetch_status("https://api.example.com") {
        ok s {
            return poll(n - 1)
        }
        fail why {
            return 0
        }
    }
}

fn main() uses io, net {
    print(to_text(poll(5)))
}
